// In-browser Turing machine stepper for the Busy Beaver page.
// Hand-written (not generated by src/build.py). The core also runs under node for tests:
//   node src/test_stepper.js
(function () {
  "use strict";

  // ------------------------------------------------------------ core
  const TAPE = 1 << 24;        // cells; the head starts in the middle
  const HALT = 255;            // "next state" value meaning halt (Z or ---)

  // Parse standard text format, e.g. 1RB1LB_1LA1RZ. "---" = undefined (counts as halting).
  function parse(text) {
    const parts = text.trim().split("_");
    const n = parts.length;
    if (!n || !parts[0]) throw new Error("규칙이 비어 있어요");
    const m = parts[0].length / 3;
    if (!Number.isInteger(m) || m < 2 || m > 9) throw new Error("상태마다 '기호·방향·다음 상태' 3글자씩 있어야 해요");
    const write = new Uint8Array(n * m), move = new Int8Array(n * m), next = new Uint8Array(n * m);
    const undef = new Uint8Array(n * m);
    parts.forEach((p, s) => {
      if (p.length !== 3 * m) throw new Error(`상태 ${String.fromCharCode(65 + s)}의 길이가 달라요`);
      for (let r = 0; r < m; r++) {
        const t = p.slice(3 * r, 3 * r + 3), i = s * m + r;
        if (t === "---") { undef[i] = 1; next[i] = HALT; move[i] = 1; continue; }
        const sym = t.charCodeAt(0) - 48, dir = t[1], st = t.charCodeAt(2) - 65;
        if (sym < 0 || sym >= m || (dir !== "L" && dir !== "R") || st < 0 || st > 25) throw new Error(`'${t}'를 읽을 수 없어요`);
        write[i] = sym; move[i] = dir === "L" ? -1 : 1; next[i] = st < n ? st : HALT;
      }
    });
    return { n, m, write, move, next, undef, text: parts.join("_") };
  }

  function machine(tm) {
    return { tm, tape: new Uint8Array(TAPE), head: TAPE >> 1, state: 0, steps: 0, nonzero: 0,
      lo: TAPE >> 1, hi: TAPE >> 1, status: "run", last: -1 };
  }

  // Run up to k steps. Returns the number of steps done. status: run | halt | undef | edge
  function run(M, k) {
    const { m, write, move, next, undef } = M.tm, tape = M.tape;
    let head = M.head, state = M.state, nz = M.nonzero, lo = M.lo, hi = M.hi, done = 0, i = -1;
    while (done < k) {
      const read = tape[head];
      i = state * m + read;
      const w = write[i];
      if (undef[i]) { M.status = "undef"; break; }  // like ./bb: reaching --- is not a step
      nz += (w !== 0) - (read !== 0);
      tape[head] = w;
      head += move[i];
      state = next[i];
      done++;
      if (head < lo) lo = head; else if (head > hi) hi = head;
      if (state === HALT) { M.status = "halt"; break; }
      if (head <= 0 || head >= TAPE - 1) { M.status = "edge"; break; }
    }
    Object.assign(M, { head, state, nonzero: nz, lo, hi, last: i });
    M.steps += done;
    return done;
  }

  const Core = { parse, machine, run, HALT };
  if (typeof module !== "undefined") { module.exports = Core; return; }

  // ------------------------------------------------------------ view
  // Same colours as src/render.py THEMES; picked by the page's colour scheme.
  const THEMES = {
    light: { pal: [[255, 255, 255], [23, 23, 23], [99, 91, 255], [0, 190, 230], [255, 89, 150],
      [130, 200, 40], [148, 163, 184], [180, 120, 255], [120, 120, 120], [200, 150, 90]], head: [255, 90, 31], empty: [240, 240, 240] },
    dark: { pal: [[13, 13, 13], [237, 237, 237], [140, 133, 255], [40, 210, 245], [255, 110, 165],
      [160, 225, 70], [148, 163, 184], [195, 150, 255], [150, 150, 150], [215, 170, 110]], head: [255, 110, 50], empty: [31, 31, 31] },
  };
  const darkQ = window.matchMedia("(prefers-color-scheme: dark)");
  let PALETTE, HEAD, EMPTY;
  function setTheme() {
    const t = THEMES[darkQ.matches ? "dark" : "light"];
    PALETTE = t.pal; HEAD = t.head; EMPTY = t.empty;
  }
  setTheme();
  const PRESETS = [
    ["BB(2) 챔피언 · 6걸음", "1RB1LB_1LA1RZ"],
    ["BB(3) 챔피언 · 21걸음", "1RB1RZ_1LB0RC_1LC1LA"],
    ["BB(4) 챔피언 · 107걸음", "1RB1LB_1LA0LC_1RZ1LD_1RD0RA"],
    ["BB(5) 챔피언 · 47,176,870걸음", "1RB1LC_1RC1RB_1RD0LE_1LA1LD_1RZ0LA"],
    ["BB(2,4) 챔피언 · 3,932,964걸음", "1RB2LA1RA1RA_1LB1LA3RB1RZ"],
    ["Antihydra (크립티드)", "1RB1RA_0LC1LE_1LD1LC_1LA0LB_1LF1RE_---0RA"],
    ["Hydra (크립티드)", "1RB3RB---3LA1RA_2LA3RA4LB0LB0LA"],
    ["Bigfoot (크립티드)", "1RB2RA1LC_2LC1RB2RB_---2LA1LA"],
    ["우리가 찾은 부채꼴 holdout", "1RB---------2LB_2LB3LA0RB4RB1LB"],
  ];
  // Slider stops: steps per frame (negative = one step every |n| frames).
  const SPEEDS = [-20, -6, 1, 10, 100, 1e3, 1e4, 1e5, 1e6];
  const SPEED_LABEL = ["초당 3걸음", "초당 10걸음", "프레임당 1걸음", "프레임당 10걸음", "프레임당 100걸음",
    "프레임당 1천 걸음", "프레임당 1만 걸음", "프레임당 10만 걸음", "프레임당 100만 걸음"];

  const root = document.getElementById("stepper");
  if (!root) return;
  const $ = s => root.querySelector(s);
  const cv = $("canvas"), ctx = cv.getContext("2d");
  const W = cv.width, H = cv.height;
  const sel = $("#st-preset"), input = $("#st-tm"), err = $("#st-err");
  const rules = $("#st-rules"), strip = $("#st-strip");
  const out = { steps: $("#st-steps"), nz: $("#st-nz"), width: $("#st-width"), status: $("#st-status") };
  const playBtn = $("#st-play"), speed = $("#st-speed"), speedLbl = $("#st-speed-lbl");
  sel.innerHTML = PRESETS.map((p, i) => `<option value="${i}">${p[0]}</option>`).join("") + `<option value="custom">직접 입력…</option>`;

  let M = null, playing = false, tick = 0, rows = [], scale = null;
  const img = ctx.createImageData(W, H);

  function load(text) {
    try {
      M = machine(parse(text));
      err.textContent = "";
    } catch (e) { err.textContent = e.message; return; }
    input.value = M.tm.text;
    rows = []; scale = null; setPlaying(false);
    pushRow(); drawRules(); paint();
  }

  // Snapshot the visited part of the tape (plus the head) as one space-time row.
  function pushRow() {
    rows.push({ lo: M.lo, cells: M.tape.slice(M.lo, M.hi + 1), head: M.head, steps: M.steps });
    if (rows.length > H) rows.shift();
  }

  // Scale: cell size in pixels from the visited range; rows are square cells when cells are big.
  function currentScale() {
    let lo = Infinity, hi = -Infinity;
    for (const r of rows) { lo = Math.min(lo, r.lo); hi = Math.max(hi, r.lo + r.cells.length - 1); }
    const span = Math.max(hi - lo + 1, 24);
    const cell = Math.max(1, Math.min(16, Math.floor(W / span)));
    const per = cell > 1 ? 1 : Math.ceil(span / W);   // cells per pixel when zoomed out
    const across = cell > 1 ? W / cell : W * per;      // cells that fit across the canvas
    return { lo: Math.floor((lo + hi + 1) / 2 - across / 2), cell, per, rowH: cell };
  }

  function drawSpaceTime() {
    const S = currentScale(), d = img.data, bg = PALETTE[0];
    for (let p = 0; p < d.length; p += 4) { d[p] = bg[0]; d[p + 1] = bg[1]; d[p + 2] = bg[2]; d[p + 3] = 255; }
    const visible = Math.floor(H / S.rowH), list = rows.slice(-visible);
    list.forEach((r, ri) => {
      const y0 = ri * S.rowH;
      const put = (x, rgb) => {
        if (x < 0 || x >= W) return;
        for (let dy = 0; dy < S.rowH; dy++) for (let dx = 0; dx < S.cell && x + dx < W; dx++) {
          const p = ((y0 + dy) * W + x + dx) * 4; d[p] = rgb[0]; d[p + 1] = rgb[1]; d[p + 2] = rgb[2];
        }
      };
      if (S.cell > 1) {
        for (let c = 0; c < r.cells.length; c++) if (r.cells[c]) put((r.lo + c - S.lo) * S.cell, PALETTE[r.cells[c]]);
        put((r.head - S.lo) * S.cell, HEAD);
      } else {
        // Many cells per pixel: largest symbol's colour, faded by the share of zeros.
        const x0 = Math.floor((r.lo - S.lo) / S.per), xs = Math.ceil(r.cells.length / S.per);
        for (let X = 0; X < xs; X++) {
          let mx = 0, cnt = 0;
          const a = X * S.per, b = Math.min(r.cells.length, a + S.per);
          for (let c = a; c < b; c++) { const v = r.cells[c]; if (v) { cnt++; if (v > mx) mx = v; } }
          if (!mx) continue;
          const f = 0.35 + 0.65 * cnt / (b - a), col = PALETTE[mx];
          put(x0 + X, [bg[0] + (col[0] - bg[0]) * f, bg[1] + (col[1] - bg[1]) * f, bg[2] + (col[2] - bg[2]) * f]);
        }
        put(Math.floor((r.head - S.lo) / S.per), HEAD);
      }
    });
    ctx.putImageData(img, 0, 0);
  }

  function drawRules() {
    const { n, m, write, move, next, undef } = M.tm;
    let h = "<thead><tr><th>상태</th>" + Array.from({ length: m }, (_, r) => `<th>${r} 읽으면</th>`).join("") + "</tr></thead><tbody>";
    for (let s = 0; s < n; s++) {
      h += `<tr><th>${String.fromCharCode(65 + s)}</th>`;
      for (let r = 0; r < m; r++) {
        const i = s * m + r;
        const t = undef[i] ? "---" : `${write[i]}${move[i] < 0 ? "L" : "R"}${next[i] === HALT ? "Z" : String.fromCharCode(65 + next[i])}`;
        h += `<td data-i="${i}"><code>${t}</code></td>`;
      }
      h += "</tr>";
    }
    rules.innerHTML = h + "</tbody>";
  }

  function paint() {
    drawSpaceTime();
    rules.querySelectorAll("td.on").forEach(td => td.classList.remove("on"));
    const nextI = M.status === "run" ? M.state * M.tm.m + M.tape[M.head] : M.last;
    const td = rules.querySelector(`td[data-i="${nextI}"]`);
    if (td) td.classList.add("on");
    // Tape strip: cells around the head.
    const R = 10;
    let s = "";
    for (let x = M.head - R; x <= M.head + R; x++) {
      const v = M.tape[x], c = v ? PALETTE[v] : EMPTY;
      s += `<span class="${x === M.head ? "hd" : ""}" style="background:rgb(${c})">${v || ""}</span>`;
    }
    strip.innerHTML = s;
    $("#st-state").textContent = M.status === "run" ? String.fromCharCode(65 + M.state) : "Z";
    out.steps.textContent = M.steps.toLocaleString("ko-KR");
    out.nz.textContent = M.nonzero.toLocaleString("ko-KR");
    out.width.textContent = (M.hi - M.lo + 1).toLocaleString("ko-KR");
    out.status.textContent = { run: "실행 중", halt: "멈춤 ✓", undef: "정해지지 않은 규칙(---)을 만나 멈춤", edge: "테이프 끝에 닿아 중단 (시뮬레이터 한계)" }[M.status];
    out.status.dataset.s = M.status;
    const per = SPEEDS[+speed.value];
    const every = per >= 1000 ? per / 8 : per;
    $("#st-rowinfo").textContent = every > 1 ? `한 줄 = ${every.toLocaleString("ko-KR")}걸음마다 찍은 테이프 (최근 ${H}줄)` : `한 줄 = 한 걸음 (최근 ${H}줄)`;
  }

  function frame() {
    if (!playing) return;
    const per = SPEEDS[+speed.value];
    if (per < 0) { if (++tick % -per === 0) { run(M, 1); pushRow(); } }
    else {
      // Fast speeds take several snapshots per frame so long runs still fill the plate.
      const k = per >= 1000 ? 8 : 1;
      for (let j = 0; j < k && M.status === "run"; j++) { run(M, per / k); pushRow(); }
    }
    paint();
    if (M.status !== "run") { setPlaying(false); return; }
    requestAnimationFrame(frame);
  }

  function setPlaying(on) {
    playing = on && M && M.status === "run";
    playBtn.textContent = playing ? "❚❚ 멈춤" : "▶ 실행";
    if (playing) requestAnimationFrame(frame);
  }

  sel.addEventListener("change", () => { if (sel.value !== "custom") load(PRESETS[+sel.value][1]); else input.focus(); });
  $("#st-load").addEventListener("click", () => { sel.value = "custom"; load(input.value); });
  input.addEventListener("keydown", e => { if (e.key === "Enter") { sel.value = "custom"; load(input.value); } });
  playBtn.addEventListener("click", () => setPlaying(!playing));
  $("#st-step").addEventListener("click", () => { setPlaying(false); if (M.status === "run") { run(M, 1); pushRow(); paint(); } });
  $("#st-reset").addEventListener("click", () => load(M.tm.text));
  speed.addEventListener("input", () => { speedLbl.textContent = SPEED_LABEL[+speed.value]; if (M) paint(); });
  speedLbl.textContent = SPEED_LABEL[+speed.value];
  darkQ.addEventListener("change", () => { setTheme(); if (M) paint(); });
  load(PRESETS[0][1]);
})();
